var n={en:`Organizations create workspaces, invite members and pay per seat. One person may belong to multiple organizations, but data must not leak across tenants.`,ua:`Організації створюють робочі простори, запрошують учасників і платять за місця. Одна особа може входити до кількох організацій, але дані між тенантами не можуть витікати.`};var t={en:[`Draw tenant resolution, authorization, domain operations and billing.`,`Define verified tenant context for every request and database query.`,`Handle duplicate invitation and seat-count changes.`],ua:[`Намалюй визначення тенанта, авторизацію, домен і білінг.`,`Визнач перевірений контекст тенанта для запитів до API та БД.`,`Оброби дублікати запрошень і змін кількості місць.`]};var s=[{en:`Tenant and roles are verified before protected domain access.`,ua:`Тенант і ролі перевіряються до захищеного доступу.`},{en:`Repeated membership events cannot charge extra seats.`,ua:`Повторні події учасників не спричиняють зайву оплату.`}];var i={scenario:n,tasks:t,checks:s};export{s as checks,i as default,n as scenario,t as tasks};